actions.script:
// TUI rich-text fields are read-only and omitted from its submit. An explicit empty value still clears.
const posted = ec.web.requestParameters || {}
const hasBody = Object.prototype.hasOwnProperty.call(posted, 'bodyHtml')
const hasInternalBody = Object.prototype.hasOwnProperty.call(posted, 'internalBodyHtml')
if (!hasBody || !hasInternalBody) {
    const current = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailOutOfOffice')
        .parameter('emailAccountId', emailAccountId).call()
    if (!ec.message.hasError()) {
        if (!hasBody) bodyHtml = current?.outOfOffice?.bodyHtml ?? null
        if (!hasInternalBody) internalBodyHtml = current?.outOfOffice?.internalBodyHtml ?? null
    }
}

service-call.in-map:
{emailAccountId:emailAccountId, enabled:(enabled == 'Y' ? 'Y' : 'N'),
                        fromDate:(fromDate || null), thruDate:(thruDate || null), subject:subject, bodyHtml:bodyHtml, internalBodyHtml:internalBodyHtml,
                        replyOncePerDays:replyOncePerDays, replyAudienceEnumId:(replyAudienceEnumId || null), internalDomains:internalDomains, applyToAll:applyToAll}

actions.script:
const current = ec.service.sync().name('org.moqui.impl.EmailClientServices.get#EmailOutOfOffice').parameter('emailAccountId', emailAccountId).call()
if (ec.message.hasError()) return
const reply = current?.outOfOffice || {}
ec.service.sync().name('org.moqui.impl.EmailClientServices.store#EmailOutOfOffice').parameters({emailAccountId: emailAccountId, enabled: false,
    fromDate: reply.fromDate ? new Date(reply.fromDate) : null, thruDate: reply.thruDate ? new Date(reply.thruDate) : null, subject: reply.subject || null,
    bodyHtml: reply.bodyHtml || null, internalBodyHtml: reply.internalBodyHtml || null, replyOncePerDays: reply.replyOncePerDays ?? 4,
    replyAudienceEnumId: reply.replyAudienceEnumId || 'EraEveryone', internalDomains: reply.internalDomains || null}).call()
if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize('Automatic reply off'), 'success')
